    DECLARE v_nombres JSON;
    DECLARE v_apellidos JSON;
    DECLARE v_paises JSON;
    DECLARE v_indice INT;

    IF p_cantidad < 1
       OR p_edad_min < 0
       OR p_edad_max < p_edad_min
       OR p_activos < 0
       OR p_activos > p_cantidad
       OR p_modo_pais NOT IN ('USA', 'MULTI') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Parametros de prueba invalidos';
    END IF;

    SET v_paises = JSON_ARRAY(
        'US','MX','CA','GB','ES',
        'FR','BR','JP','KR','DE'
    );

    WHILE v_i < p_cantidad DO

        IF p_modo_pais = 'USA' THEN
            SET v_pais = 'US';
        ELSE
            SET v_pais = JSON_UNQUOTE(
                JSON_EXTRACT(
                    v_paises,
                    CONCAT(
                        '$[',
                        FLOOR(RAND() * JSON_LENGTH(v_paises)),
                        ']'
                    )
                )
            );
        END IF;

        CASE v_pais
            WHEN 'US' THEN
