                );
                SET v_apellidos = JSON_ARRAY(
                    'Smith','Brown','Tremblay','Martin',
                    'Roy','Wilson','MacDonald','Gagnon'
                );

            WHEN 'GB' THEN
                SET v_nombres = JSON_ARRAY(
                    'Oliver','George','Harry','Jack',
                    'Amelia','Isla','Freya','Emily'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Smith','Jones','Williams','Brown',
                    'Taylor','Davies','Wilson','Evans'
                );

            WHEN 'ES' THEN
                SET v_nombres = JSON_ARRAY(
                    'Hugo','Martin','Lucas','Mateo',
                    'Lucia','Martina','Sofia','Julia'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Garcia','Rodriguez','Gonzalez','Fernandez',
                    'Lopez','Martinez','Sanchez','Perez'
                );

            WHEN 'FR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Gabriel','Louis','Raphael','Jules',
                    'Emma','Jade','Louise','Alice'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Martin','Bernard','Dubois','Thomas',
                    'Robert','Richard','Petit','Durand'
                );

            WHEN 'BR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Miguel','Arthur','Heitor','Gabriel',
                    'Helena','Alice','Laura','Valentina'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Silva','Santos','Oliveira','Souza',
                    'Pereira','Costa','Rodrigues','Almeida'
                );

            WHEN 'JP' THEN
                SET v_nombres = JSON_ARRAY(
                    'Haruto','Ren','Yuto','Sota',
                    'Yui','Hina','Aoi','Sakura'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Sato','Suzuki','Takahashi','Tanaka',
