            v_nick,
            v_password,
            NULL,
            v_nombre,
            v_apellido,
            v_nacimiento,
            v_genero,
            v_pais,
            v_telefono
        );

        SET v_user_id = LAST_INSERT_ID();

        IF v_i >= p_activos THEN
            UPDATE tb_users
            SET status = b'0'
            WHERE ID = v_user_id;
        END IF;

        SET v_i = v_i + 1;

    END WHILE;

    SELECT
        p_cantidad AS cantidad_solicitada,
        p_activos AS activos_solicitados,
        p_cantidad - p_activos AS inactivos_solicitados,
        p_modo_pais AS modo_pais,
        p_edad_min AS edad_minima,
        p_edad_max AS edad_maxima;

END ;;
