                    'Pereira','Costa','Rodrigues','Almeida'
                );

            WHEN 'JP' THEN
                SET v_nombres = JSON_ARRAY(
                    'Haruto','Ren','Yuto','Sota',
                    'Yui','Hina','Aoi','Sakura'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Sato','Suzuki','Takahashi','Tanaka',
                    'Watanabe','Ito','Yamamoto','Nakamura'
                );

            WHEN 'KR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Min-jun','Seo-jun','Do-yun','Ji-ho',
                    'Seo-yeon','Ji-woo','Ha-eun','Min-seo'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Kim','Lee','Park','Choi',
                    'Jung','Kang','Cho','Yoon'
                );

            WHEN 'DE' THEN
                SET v_nombres = JSON_ARRAY(
                    'Leon','Paul','Felix','Lukas',
                    'Emilia','Mia','Hannah','Lina'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Mueller','Schmidt','Schneider','Fischer',
                    'Weber','Meyer','Wagner','Becker'
                );
        END CASE;

        SET v_indice = FLOOR(
            RAND() * JSON_LENGTH(v_nombres)
        );

        SET v_nombre = JSON_UNQUOTE(
            JSON_EXTRACT(
                v_nombres,
                CONCAT('$[', v_indice, ']')
            )
        );

        SET v_indice = FLOOR(
            RAND() * JSON_LENGTH(v_apellidos)
        );

        SET v_apellido = JSON_UNQUOTE(
            JSON_EXTRACT(
                v_apellidos,
                CONCAT('$[', v_indice, ']')
            )
        );

        SET v_edad = p_edad_min
            + FLOOR(
                RAND() * (p_edad_max - p_edad_min + 1)
            );

        SET v_nacimiento = DATE_SUB(
            DATE_SUB(CURDATE(), INTERVAL v_edad YEAR),
            INTERVAL FLOOR(RAND() * 300) DAY
        );

        SET v_genero = ELT(
            FLOOR(RAND() * 3) + 1,
            'Hombre',
            'Mujer',
            'Prefiero no decirlo'
        );

        SET v_email = CONCAT(
            'prueba.',
            REPLACE(UUID(), '-', ''),
            '@example.com'
        );

        SET v_nick = CONCAT(
            'test_',
            REPLACE(UUID(), '-', '')
        );

        SET v_password = CONCAT(
            'Prueba_',
            LEFT(REPLACE(UUID(), '-', ''), 20),
            '!'
        );

        SET v_telefono = CONCAT(
            '+',
            CASE v_pais
                WHEN 'US' THEN '1'
                WHEN 'MX' THEN '52'
                WHEN 'CA' THEN '1'
                WHEN 'GB' THEN '44'
                WHEN 'ES' THEN '34'
                WHEN 'FR' THEN '33'
                WHEN 'BR' THEN '55'
                WHEN 'JP' THEN '81'
                WHEN 'KR' THEN '82'
                WHEN 'DE' THEN '49'
            END,
            '000000',
            LPAD(v_i MOD 10000, 4, '0')
        );

        CALL sp_register_new_user(
            v_email,
            v_nick,
            v_password,
            NULL,
            v_nombre,
            v_apellido,
            v_nacimiento,
            v_genero,
            v_pais,
            v_telefono
        );

        SET v_user_id = LAST_INSERT_ID();

        IF v_i >= p_activos THEN
            UPDATE tb_users
            SET status = b'0'
            WHERE ID = v_user_id;
        END IF;

        SET v_i = v_i + 1;

    END WHILE;

    SELECT
        p_cantidad AS cantidad_solicitada,
        p_activos AS activos_solicitados,
        p_cantidad - p_activos AS inactivos_solicitados,
        p_modo_pais AS modo_pais,
        p_edad_min AS edad_minima,
        p_edad_max AS edad_maxima;

END ;;
DELIMITER ;
